export const N=80;
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function sample(g,x,y,w,h){let u=clamp(x/w*N,0,N),v=clamp(y/h*N,0,N),i=Math.min(N-1,Math.floor(u)),j=Math.min(N-1,Math.floor(v));u-=i;v-=j;let k=j*(N+1)+i,a=g[k],b=g[k+1],c=g[k+N+2],d=g[k+N+1];return u>=v?a*(1-u)+b*(u-v)+c*v:a*(1-v)+c*u+d*(v-u)}
export function grid(fn,w,h){return Array.from({length:(N+1)**2},(_,k)=>fn(k%(N+1)*w/N,Math.floor(k/(N+1))*h/N))}
export function contours(g,w,h,step){if(!(Number.isFinite(step)&&step>0))throw Error('等高距必須為大於零的有限數值');const lo=Math.min(...g),hi=Math.max(...g),out=[];if((hi-lo)/step>500)throw Error('等高線超過 500 層，請增加等高距');for(let k=Math.ceil(lo/step);k*step<=hi;k++){const z=k*step,segs=[];for(let j=0;j<N;j++)for(let i=0;i<N;i++){const ids=[j*(N+1)+i,j*(N+1)+i+1,(j+1)*(N+1)+i+1,(j+1)*(N+1)+i],ps=[[i*w/N,j*h/N],[(i+1)*w/N,j*h/N],[(i+1)*w/N,(j+1)*h/N],[i*w/N,(j+1)*h/N]];for(const tri of [[0,1,2],[0,2,3]]){let cross=[];for(let t=0;t<3;t++){let a=tri[t],b=tri[(t+1)%3],za=g[ids[a]],zb=g[ids[b]];if((za<z)!==(zb<z)){let f=(z-za)/(zb-za);cross.push([ps[a][0]+f*(ps[b][0]-ps[a][0]),ps[a][1]+f*(ps[b][1]-ps[a][1])])}}if(cross.length===2)segs.push(cross)}}if(segs.length)out.push({z,major:((k%5)+5)%5===0,segs})}return out}
export function volume(a,b,w,h){let cut=0,fill=0;const dx=w/N,dy=h/N;
function positive(tri,sign){let poly=tri.map(p=>[p[0],p[1],p[2]*sign]),clipped=[];for(let i=0;i<3;i++){let p=poly[i],q=poly[(i+1)%3];if(p[2]>=0)clipped.push(p);if((p[2]>=0)!==(q[2]>=0)){let t=p[2]/(p[2]-q[2]);clipped.push([p[0]+t*(q[0]-p[0]),p[1]+t*(q[1]-p[1]),0])}}let v=0;for(let i=1;i<clipped.length-1;i++){let p=clipped[0],q=clipped[i],r=clipped[i+1],area=Math.abs((q[0]-p[0])*(r[1]-p[1])-(r[0]-p[0])*(q[1]-p[1]))/2;v+=area*(p[2]+q[2]+r[2])/3}return v}
for(let j=0;j<N;j++)for(let i=0;i<N;i++){let k=j*(N+1)+i,ids=[k,k+1,k+N+2,k+N+1],ps=[[0,0],[dx,0],[dx,dy],[0,dy]].map((p,n)=>[...p,b[ids[n]]-a[ids[n]]]);for(let tri of [[ps[0],ps[1],ps[2]],[ps[0],ps[2],ps[3]]]){fill+=positive(tri,1);cut+=positive(tri,-1)}}return{cut,fill,net:fill-cut}}
export function idw(points,w,h){if(!points.length||!points.every(p=>p.length===3&&p.every(Number.isFinite)))throw Error('內插需要有效高程點');return grid((x,y)=>{let best=[];for(let p of points){let d=(p[0]-x)**2+(p[1]-y)**2;if(d<1e-12)return p[2];if(best.length<12||d<best[best.length-1][0]){best.push([d,p[2]]);best.sort((a,b)=>a[0]-b[0]);if(best.length>12)best.pop()}}let a=0,b=0;for(let [d,z] of best){let wt=1/(d*d);a+=wt*z;b+=wt}return a/b},w,h)}
export function parsePoints(buffer,name,unit=1,up='z'){const text=()=>new TextDecoder().decode(buffer),ext=name.toLowerCase().split('.').pop();let pts=[];if(ext==='obj'){for(let l of text().split(/\r?\n/))if(/^\s*v\s/.test(l))pts.push(l.trim().split(/\s+/).slice(1,4).map(Number))}else if(ext==='stl'){let dv=new DataView(buffer),count=buffer.byteLength>=84?dv.getUint32(80,true):0;if(84+count*50===buffer.byteLength){for(let i=0;i<count;i++)for(let v=0;v<3;v++)pts.push([0,1,2].map(k=>dv.getFloat32(84+i*50+12+v*12+k*4,true)))}else{for(let m of text().matchAll(/vertex\s+([-+\deE.]+)\s+([-+\deE.]+)\s+([-+\deE.]+)/g))pts.push(m.slice(1).map(Number))}}else if(ext==='ply'){let t=text();if(!/format ascii/.test(t))throw Error('PLY 請先匯出為 ASCII 格式');let end=t.indexOf('end_header'),head=t.slice(0,end),count=Number(head.match(/element vertex (\d+)/)?.[1]);let block=head.split(/element vertex \d+/)[1]?.split(/element /)[0]||'',props=[...block.matchAll(/property \S+ (\S+)/g)].map(x=>x[1]),ids=['x','y','z'].map(x=>props.indexOf(x));if(ids.includes(-1))throw Error('PLY 缺少 x/y/z');for(let l of t.slice(end+10).trim().split(/\r?\n/).slice(0,count)){let v=l.trim().split(/\s+/).map(Number);pts.push(ids.map(i=>v[i]))}}else if(['xyz','csv','txt'].includes(ext)){for(let l of text().split(/\r?\n/)){let v=l.trim().split(/[,;\s]+/).slice(0,3).map(Number);if(v.length===3&&v.every(Number.isFinite))pts.push(v)}}else throw Error('不支援此格式，請使用 OBJ、STL、ASCII PLY、XYZ、CSV 或 ASC');if(!(Number.isFinite(unit)&&unit>0))throw Error('檔案單位無效');pts=pts.filter(p=>p.length===3&&p.every(Number.isFinite)).map(p=>up==='y'?[p[0]*unit,-p[2]*unit,p[1]*unit]:p.map(v=>v*unit));if(!pts.every(p=>p.every(Number.isFinite)))throw Error('換算後座標超過可用範圍');if(['obj','stl'].includes(ext)){let top=new Map();for(let p of pts){let k=p[0]+','+p[1];if(!top.has(k)||p[2]>top.get(k)[2])top.set(k,p)}pts=[...top.values()]}if(pts.length<3)throw Error('沒有足夠有效三維座標');const min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];pts.forEach(p=>p.forEach((v,i)=>{min[i]=Math.min(min[i],v);max[i]=Math.max(max[i],v)}));let w=max[0]-min[0],h=max[1]-min[1];if(w<.01||h<.01)throw Error('水平範圍不足，請檢查高程軸或檔案單位');const stride=Math.max(1,Math.ceil(pts.length/6000));pts=pts.filter((_,i)=>i%stride===0).map(p=>[p[0]-min[0],p[1]-min[1],p[2]]);return{pts,w,h,origin:min.slice(0,2)}}
export function parseASC(text){let lines=text.trim().split(/\r?\n/),meta={},row=0;while(row<lines.length&&/^[a-z]/i.test(lines[row].trim())){let [key,val]=lines[row++].trim().split(/\s+/);meta[key.toLowerCase()]=Number(val)}let {ncols:c,nrows:r,cellsize:s}=meta,vals=lines.slice(row).join(' ').trim().split(/\s+/).map(Number);if(!Number.isInteger(c)||!Number.isInteger(r)||c<2||r<2||!(s>0)||vals.length!==c*r)throw Error('ASC 網格標頭或資料數量不正確');let pts=[];const stride=Math.max(1,Math.ceil(Math.sqrt(c*r/6000)));for(let j=0;j<r;j+=stride)for(let i=0;i<c;i+=stride){let z=vals[j*c+i];if(Number.isFinite(z)&&z!==meta.nodata_value)pts.push([i*s,(r-1-j)*s,z])}if(pts.length<3)throw Error('ASC 沒有足夠有效高程');return{pts,w:(c-1)*s,h:(r-1)*s,origin:[meta.xllcenter??((meta.xllcorner??0)+s/2),meta.yllcenter??((meta.yllcorner??0)+s/2)]}}
